include!("src/app_commands.rs");

/// The permission set the capability grants the host webview: every
/// command in `APP_COMMANDS`, written from it so the two cannot drift.
fn write_permission_set() {
    let permissions: Vec<String> = APP_COMMANDS
        .iter()
        .map(|c| format!("  \"allow-{}\",", c.replace('_', "-")))
        .collect();
    let toml = format!(
        "# Generated by build.rs from src/app_commands.rs - do not edit.\n\n\
         [[set]]\n\
         identifier = \"app-commands\"\n\
         description = \"Every command of the app, for its own webview only.\"\n\
         permissions = [\n{}\n]\n",
        permissions.join("\n")
    );
    let path = std::path::Path::new("permissions/app-commands.toml");
    if std::fs::read_to_string(path).ok().as_deref() != Some(toml.as_str()) {
        std::fs::create_dir_all("permissions").unwrap();
        std::fs::write(path, toml).unwrap();
    }
}

fn main() {
    println!("cargo:rerun-if-changed=src/app_commands.rs");
    println!("cargo:rerun-if-changed=permissions");
    write_permission_set();
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS)),
    )
    .expect("tauri-build");
}
